// 必须紧随原begin成功；新头失败由同一Common/Task外层保存点一起撤回。
#include "task_shop_order_contact_detail.hpp"
namespace hanmo::resident {
Outcome<StableId> record_task_shop_order_contact_in_candidate(CommonStore& c,TaskShopOrderContactState& state,const TaskShopOrderContactContext& x,const StableId& id,const TaskShopOrderDeliveryQuote& quote){
 using namespace shop_contact_detail;auto fail=[&](const StableId& code)->Outcome<StableId>{return {false,{},common_failure(code,id).error};};if(&c!=&x.common||&state!=&x.contacts||x.phase||state.version!=1||!identity(quote.source_identity,c.state().identity)||quote.duration!=task_handover_ticks)return fail("TaskShopOrderContactCandidateMismatch");
 const auto* action=c.action(id);const auto* original=x.orders.actions.find(id);const auto* b=binding(x.orders,quote.task_id);const auto& meeting=quote.contact.meeting;const auto number=serial(c,id,"action");
 if(!action||!original||!b||!number||*number!=c.state().next_instance_id-1||original->task_id!=quote.task_id||original->session_id!=meeting.session_id||original->dialogue_id!=meeting.dialogue_id||original->node_id!=meeting.node_id||!context(original->context,meeting.context)||meeting.actor_id!=b->terms.proprietor_actor_id||quote.contact.speaker_actor_id!=b->terms.original_client.id||action->kind!="task_shop_order_deliver"||action->actor_id!=meeting.actor_id||action->participants!=std::vector<StableId>{meeting.actor_id,meeting.context.provider_actor_id}||action->start_tick!=c.tick()||action->remaining_ticks!=task_handover_ticks||original->started_tick!=c.tick())return fail("TaskShopOrderOriginalStartRequired");for(const auto& row:state.starts.rows())if(row.second.action_id==id)return fail("TaskShopOrderContactAlreadyRecorded");
 for(const auto& person:action->participants){const auto* actor=c.actor(person);if(!actor||actor->action_id!=id)return fail("TaskShopOrderContactOccupationMismatch");}
 auto fact=c.next_id(task_shop_order_contact_started_kind);if(!fact.ok)return fact;TaskShopOrderContactStart s;s.fact_id=fact.value;s.task_id=b->task_id;s.order_id=b->order_id;s.acceptance_fact_id=b->fact_id;s.order_issue_fact_id=b->order_issue_fact_id;s.proprietor_actor_id=b->terms.proprietor_actor_id;s.client_actor_id=b->terms.original_client.id;s.action_id=id;s.session_id=original->session_id;s.dialogue_id=original->dialogue_id;s.node_id=original->node_id;s.context=original->context;s.context.field_order.clear();s.started_tick=original->started_tick;
 auto valid=c.append_fact({s.fact_id,task_shop_order_contact_started_kind,task_shop_order_contact_module});if(!valid.ok)return {false,{},valid.error};valid=source(x,s);if(!valid.ok)return {false,{},valid.error};const auto contact_id=s.fact_id;if(!state.starts.insert(contact_id,std::move(s)))return fail("DuplicateTaskShopOrderContact");return fact;
}
}
